<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import InvitationPreviewRenderer from '@/Components/InvitationPreviewRenderer.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { computed, watch } from 'vue';

const props = defineProps<{ event: any; step: number; templates: any[]; overrides: any; resolvedSettings: any; activities: any[]; meals: any[]; previewInvitation: any; workflow: any; timezones: string[] }>();
const dateValue = (value: string | null | undefined) => value ? value.slice(0, 10) : '';
const timeValue = (value: string | null | undefined) => value ? value.slice(0, 5) : '';
const details = useForm({ event_type: props.event.event_type || '', title: props.event.title || '', host_name: props.event.host_name || '', second_host_name: props.event.second_host_name || '', description: props.event.description || '' });
const location = useForm({ main_date: dateValue(props.event.main_date), start_time: timeValue(props.event.start_time), end_time: timeValue(props.event.end_time), event_timezone: props.event.event_timezone || '', venue: props.event.venue || '', address: props.event.address || '', location_url: props.event.location_url || '', dress_code: props.event.dress_code || '', parking_information: props.event.parking_information || '', transportation_information: props.event.transportation_information || '', accommodation_information: props.event.accommodation_information || '', guest_information: props.event.guest_information || '' });
const rsvp = useForm({ rsvp_deadline: dateValue(props.event.rsvp_deadline) });
const design = useForm({ template_id: props.event.template_id || '', settings: { palette_key: props.overrides.palette_key || '', font_pair_key: props.overrides.font_pair_key || '' } });
const publish = useForm({});
const selectedTemplate = computed(() => props.templates.find((template) => template.id === Number(design.template_id)) || null);
const paletteOptions = computed(() => selectedTemplate.value?.palettes || []);
const fontPairOptions = computed(() => selectedTemplate.value?.font_pairs || []);
const previewInvitation = computed(() => ({ ...props.previewInvitation, template: selectedTemplate.value ? { name: selectedTemplate.value.name, component_key: selectedTemplate.value.component_key } : props.previewInvitation.template, settings: { ...props.resolvedSettings, ...(paletteOptions.value.find((item: any) => item.key === design.settings.palette_key) || {}), ...(fontPairOptions.value.find((item: any) => item.key === design.settings.font_pair_key) || {}) } }));
watch(() => design.template_id, (current, previous) => { if (previous !== undefined && current !== previous) { design.settings.palette_key = ''; design.settings.font_pair_key = ''; } });
const saveDetails = () => details.patch(route('events.setup.save', { event: props.event.id, step: 'details' }));
const saveLocation = () => location.patch(route('events.setup.save', { event: props.event.id, step: 'location' }));
const saveRsvp = () => rsvp.patch(route('events.setup.save', { event: props.event.id, step: 'rsvp' }));
const saveDesign = () => design.transform((data) => ({ template_id: data.template_id, settings: { palette_key: data.settings.palette_key || null, font_pair_key: data.settings.font_pair_key || null } })).patch(route('events.setup.save', { event: props.event.id, step: 'design' }));
</script>

<template>
    <Head :title="`${event.title} Invitation Setup`" />
    <AuthenticatedLayout>
        <template #header><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-xl font-semibold">Invitation Setup</h2><p class="text-sm text-gray-600">Build, preview, and publish your invitation.</p></div><Link :href="route('events.show', event.id)" class="rounded border border-gray-300 px-3 py-2 text-sm">Back to Event</Link></div></template>
        <div class="mx-auto max-w-6xl space-y-6 p-6">
            <nav class="grid gap-2 sm:grid-cols-5" aria-label="Invitation setup steps"><Link v-for="(name, index) in ['Event Details', 'Date & Location', 'Schedule & RSVP', 'Choose Design', 'Review & Publish']" :key="name" :href="route('events.setup', { event: event.id, step: index + 1 })" class="rounded border px-3 py-3 text-sm" :class="step === index + 1 ? 'border-indigo-600 bg-indigo-50 font-medium text-indigo-800' : 'border-gray-200 bg-white text-gray-700'"><span class="mr-1 text-xs">{{ index + 1 }}</span>{{ name }}</Link></nav>
            <p v-if="!workflow.can_manage" class="rounded border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">You can view this invitation setup, but your role is read-only.</p>

            <form v-if="step === 1" class="space-y-5 rounded bg-white p-6 shadow" @submit.prevent="saveDetails"><div><h3 class="text-lg font-semibold">Event Details</h3><p class="mt-1 text-sm text-gray-600">Tell guests what they are celebrating and who is hosting.</p></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="block text-sm font-medium">Event type</label><select v-model="details.event_type" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"><option value="">Select type</option><option v-for="type in ['wedding', 'engagement', 'bridal_shower', 'birthday', 'graduation', 'baptism', 'communion']" :key="type" :value="type">{{ type.replaceAll('_', ' ') }}</option></select><InputError :message="details.errors.event_type" class="mt-1" /></div><div><label class="block text-sm font-medium">Event title</label><input v-model="details.title" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"><InputError :message="details.errors.title" class="mt-1" /></div><div><label class="block text-sm font-medium">Host name</label><input v-model="details.host_name" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"><InputError :message="details.errors.host_name" class="mt-1" /></div><div><label class="block text-sm font-medium">Second host name</label><input v-model="details.second_host_name" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"></div><div class="sm:col-span-2"><label class="block text-sm font-medium">Description</label><textarea v-model="details.description" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300" rows="5" /></div></div><div v-if="workflow.can_manage" class="flex justify-end"><button :disabled="details.processing" class="rounded bg-indigo-600 px-4 py-2 text-white disabled:opacity-60">Save &amp; Continue</button></div></form>

            <form v-else-if="step === 2" class="space-y-5 rounded bg-white p-6 shadow" @submit.prevent="saveLocation"><div><h3 class="text-lg font-semibold">Date &amp; Location</h3><p class="mt-1 text-sm text-gray-600">Times are interpreted in the selected Event timezone.</p></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="block text-sm font-medium">Main date</label><input v-model="location.main_date" :disabled="!workflow.can_manage" type="date" class="mt-1 w-full rounded border-gray-300"><InputError :message="location.errors.main_date" class="mt-1" /></div><div><label class="block text-sm font-medium">Event timezone</label><select v-model="location.event_timezone" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"><option value="">Select timezone</option><option v-for="timezone in timezones" :key="timezone" :value="timezone">{{ timezone }}</option></select><InputError :message="location.errors.event_timezone" class="mt-1" /></div><div><label class="block text-sm font-medium">Start time</label><input v-model="location.start_time" :disabled="!workflow.can_manage" type="time" class="mt-1 w-full rounded border-gray-300"><InputError :message="location.errors.start_time" class="mt-1" /></div><div><label class="block text-sm font-medium">End time</label><input v-model="location.end_time" :disabled="!workflow.can_manage" type="time" class="mt-1 w-full rounded border-gray-300"><InputError :message="location.errors.end_time" class="mt-1" /></div><div><label class="block text-sm font-medium">Venue</label><input v-model="location.venue" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"></div><div><label class="block text-sm font-medium">Address</label><input v-model="location.address" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"></div><div class="sm:col-span-2"><label class="block text-sm font-medium">Location URL</label><input v-model="location.location_url" :disabled="!workflow.can_manage" type="url" class="mt-1 w-full rounded border-gray-300"><InputError :message="location.errors.location_url" class="mt-1" /></div><div><label class="block text-sm font-medium">Dress code</label><textarea v-model="location.dress_code" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300" /></div><div><label class="block text-sm font-medium">Parking information</label><textarea v-model="location.parking_information" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300" /></div><div><label class="block text-sm font-medium">Transportation information</label><textarea v-model="location.transportation_information" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300" /></div><div><label class="block text-sm font-medium">Accommodation information</label><textarea v-model="location.accommodation_information" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300" /></div><div class="sm:col-span-2"><label class="block text-sm font-medium">Guest information</label><textarea v-model="location.guest_information" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300" /></div></div><div class="flex justify-between"><Link :href="route('events.setup', { event: event.id, step: 1 })" class="rounded border px-4 py-2">Back</Link><button v-if="workflow.can_manage" :disabled="location.processing" class="rounded bg-indigo-600 px-4 py-2 text-white disabled:opacity-60">Save &amp; Continue</button></div></form>

            <form v-else-if="step === 3" class="space-y-6 rounded bg-white p-6 shadow" @submit.prevent="saveRsvp"><div><h3 class="text-lg font-semibold">Schedule &amp; RSVP</h3><p class="mt-1 text-sm text-gray-600">Activities and meal choices remain separate Event tools, available here when you need them.</p></div><div><label class="block text-sm font-medium">RSVP deadline</label><input v-model="rsvp.rsvp_deadline" :disabled="!workflow.can_manage" type="date" class="mt-1 rounded border-gray-300"><InputError :message="rsvp.errors.rsvp_deadline" class="mt-1" /></div><div class="grid gap-5 lg:grid-cols-2"><section class="rounded border p-4"><div class="flex items-center justify-between"><h4 class="font-medium">Schedule</h4><Link :href="route('events.activities.index', event.id)" class="text-sm text-indigo-600 underline">Manage schedule</Link></div><ul v-if="activities.length" class="mt-3 divide-y text-sm"><li v-for="activity in activities" :key="activity.id" class="py-2"><strong>{{ activity.title }}</strong><span class="block text-gray-600">{{ activity.starts_at }} · {{ activity.is_active ? 'Active' : 'Inactive' }}</span></li></ul><p v-else class="mt-3 text-sm text-gray-600">No activities added yet.</p></section><section class="rounded border p-4"><div class="flex items-center justify-between"><h4 class="font-medium">Meal options</h4><Link :href="route('events.rsvps.index', event.id)" class="text-sm text-indigo-600 underline">Manage meals</Link></div><ul v-if="meals.length" class="mt-3 divide-y text-sm"><li v-for="meal in meals" :key="meal.id" class="py-2"><strong>{{ meal.name }}</strong><span class="ml-2 text-gray-600">{{ meal.is_active ? 'Active' : 'Inactive' }}</span></li></ul><p v-else class="mt-3 text-sm text-gray-600">No meal options added yet.</p></section></div><div class="flex justify-between"><Link :href="route('events.setup', { event: event.id, step: 2 })" class="rounded border px-4 py-2">Back</Link><button v-if="workflow.can_manage" :disabled="rsvp.processing" class="rounded bg-indigo-600 px-4 py-2 text-white disabled:opacity-60">Save &amp; Continue</button></div></form>

            <form v-else-if="step === 4" class="space-y-6" @submit.prevent="saveDesign"><section class="rounded bg-white p-6 shadow"><h3 class="text-lg font-semibold">Choose Design</h3><p class="mt-1 text-sm text-gray-600">Choose a trusted Template, then select its approved color style and typography.</p><div class="mt-5 grid gap-4 md:grid-cols-3"><button v-for="template in templates" :key="template.id" type="button" :disabled="!workflow.can_manage" class="rounded border p-4 text-left transition" :class="Number(design.template_id) === template.id ? 'border-indigo-600 ring-2 ring-indigo-100' : 'border-gray-200'" @click="design.template_id = template.id"><span class="block h-16 rounded" :class="template.component_key === 'romantic-floral' ? 'bg-rose-100' : template.component_key === 'editorial-luxury' ? 'bg-amber-100' : 'bg-slate-800'"></span><strong class="mt-3 block">{{ template.name }}</strong><span class="mt-1 block text-sm text-gray-600">{{ template.description || 'Premium invitation design' }}</span></button></div><InputError :message="design.errors.template_id" class="mt-2" /><div v-if="selectedTemplate" class="mt-6 grid gap-4 sm:grid-cols-2"><div><label class="block text-sm font-medium">Color style</label><select v-model="design.settings.palette_key" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"><option value="">Use Template default</option><option v-for="palette in paletteOptions" :key="palette.key" :value="palette.key">{{ palette.label }}</option></select><InputError :message="design.errors['settings.palette_key']" class="mt-1" /></div><div><label class="block text-sm font-medium">Typography</label><select v-model="design.settings.font_pair_key" :disabled="!workflow.can_manage" class="mt-1 w-full rounded border-gray-300"><option value="">Use Template default</option><option v-for="font in fontPairOptions" :key="font.key" :value="font.key">{{ font.label }}</option></select><InputError :message="design.errors['settings.font_pair_key']" class="mt-1" /></div></div><div class="mt-6 flex justify-between"><Link :href="route('events.setup', { event: event.id, step: 3 })" class="rounded border px-4 py-2">Back</Link><button v-if="workflow.can_manage" :disabled="design.processing" class="rounded bg-indigo-600 px-4 py-2 text-white disabled:opacity-60">Save &amp; Continue</button></div></section><InvitationPreviewRenderer :invitation="previewInvitation" /></form>

            <section v-else class="space-y-6 rounded bg-white p-6 shadow"><div><h3 class="text-lg font-semibold">Review &amp; Publish</h3><p class="mt-1 text-sm text-gray-600">Check your saved invitation information before making it live.</p></div><dl class="grid gap-4 sm:grid-cols-2"><div><dt class="text-sm text-gray-500">Event Details</dt><dd>{{ event.title || 'Needs attention' }} · {{ event.host_name || 'Host needed' }}</dd></div><div><dt class="text-sm text-gray-500">Date &amp; Location</dt><dd>{{ dateValue(event.main_date) || 'Date needed' }} · {{ event.venue || 'Venue not provided' }}</dd></div><div><dt class="text-sm text-gray-500">Schedule &amp; RSVP</dt><dd>{{ activities.length }} activities · {{ meals.length }} meal options</dd></div><div><dt class="text-sm text-gray-500">Design</dt><dd>{{ event.template?.name || 'Template needed' }}</dd></div></dl><p v-if="workflow.archived" class="rounded border border-red-200 bg-red-50 p-4 text-sm text-red-800">This Event is archived and cannot be published.</p><p v-else-if="workflow.live_version && !workflow.unpublished_changes" class="rounded border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800">Invitation is up to date — Version {{ workflow.live_version }} is live.</p><div class="flex flex-wrap justify-between gap-3"><Link :href="route('events.setup', { event: event.id, step: 4 })" class="rounded border px-4 py-2">Back</Link><div class="flex gap-2"><Link :href="route('events.invitation.preview', event.id)" class="rounded border border-indigo-600 px-4 py-2 text-indigo-700">Preview Invitation</Link><button v-if="workflow.can_manage && !workflow.archived && (!workflow.live_version || workflow.unpublished_changes)" :disabled="publish.processing" class="rounded bg-slate-900 px-4 py-2 text-white disabled:opacity-60" @click="publish.post(route('events.publication.publish', event.id))">{{ workflow.live_version ? 'Publish Changes' : 'Publish Invitation' }}</button></div></div><div v-if="publish.errors" class="text-sm text-red-700"><p v-for="(message, key) in publish.errors" :key="key">{{ message }}</p></div></section>
        </div>
    </AuthenticatedLayout>
</template>
